<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
const { t } = useI18n()
import ConfirmDialog from '../components/ConfirmDialog.vue'
import AttentionNotice from '../components/AttentionNotice.vue'
import ListFilters from '../components/ListFilters.vue'
import ListPagination from '../components/ListPagination.vue'
import PageHeader from '../components/PageHeader.vue'
import { api } from '../lib/api'
import { formatDateTime } from '../lib/formatDate'
import { useModelDiscovery } from '../lib/modelDiscovery'
import { usePagedList } from '../lib/pagination'
import { toast } from '../lib/toast'
import type { AgentDefault, GenerationInput, GenerationModelChoice, GenerationRun, Job, LLMConnection, Profile, Template } from '../lib/types'

const profiles=ref<Profile[]>([]),opportunities=ref<Job[]>([]),templates=ref<Template[]>([]),connections=ref<LLMConnection[]>([]),runs=ref<GenerationRun[]>([])
const loading=ref(true),submitting=ref(false),deletingId=ref(''),pendingDelete=ref<GenerationRun|null>(null),showCreate=ref(false),error=ref(''),useSpecifiedModel=ref(false)
const search=ref(''),stateFilter=ref('all')
const emptyChoice=():GenerationModelChoice=>({connectionId:'',model:''})
const form=reactive<GenerationInput>({profileId:'',opportunityId:'',templateId:'',documentType:'resume',language:'English',pageTarget:'one_page',customInstructions:'',pipelineMode:'multi',writer:emptyChoice(),renderer:emptyChoice(),reviewer:emptyChoice()})
const writerDefault=ref<GenerationModelChoice|null>(null),templateApplierDefault=ref<GenerationModelChoice|null>(null),designerDefault=ref<GenerationModelChoice|null>(null),reviewerDefault=ref<GenerationModelChoice|null>(null)
let timer:number|undefined
const matchingTemplates=computed(()=>templates.value.filter(item=>item.state==='ready'&&item.kind===form.documentType))
const latexTemplates=computed(()=>matchingTemplates.value.filter(item=>item.format==='latex'))
const ready=computed(()=>Boolean(form.profileId&&form.opportunityId&&form.writer.connectionId&&form.writer.model&&(form.pipelineMode==='single'||(form.renderer.connectionId&&form.renderer.model&&form.reviewer.connectionId&&form.reviewer.model))))
const active=computed(()=>runs.value.some(item=>item.state==='queued'||item.state==='running'))
const optionName=(values:{id:string;name?:string;title?:string;company?:string}[],id:string)=>{const value=values.find(item=>item.id===id);return value?.name??([value?.title,value?.company].filter(Boolean).join(' · ')||t('generate.deletedInput'))}
const stageLabel=(run:GenerationRun)=>run.state==='failed'?t('common.needsAttention'):({queued:t('generate.stage.waiting'),writing:t('generate.stage.writing'),rendering:run.templateId?t('generate.stage.applyingTemplate'):t('generate.stage.designingDocument'),reviewing:t('generate.stage.visualQa'),repairing:t('generate.stage.repairing',{count:run.repairCount}),finalizing:t('generate.stage.finalizing'),ready:t('generate.stage.ready')} as Record<string,string>)[run.stage]??run.stage
const stageProgress=(run:GenerationRun)=>run.state==='failed'?100:({queued:8,writing:20,rendering:42,reviewing:64,repairing:82,finalizing:94,ready:100} as Record<string,number>)[run.stage]??0
const formatDate=(value:string)=>formatDateTime(value)
const pageTargetLabel=(value:string)=>({one_page:t('generate.pageTarget.onePage'),two_pages:t('generate.pageTarget.twoPages'),flexible:t('generate.pageTarget.flexible')} as Record<string,string>)[value]??value.replace('_',' ')
const filteredRuns=computed(()=>{const query=search.value.trim().toLocaleLowerCase();return runs.value.filter(run=>{const values=[optionName(opportunities.value,run.opportunityId),optionName(profiles.value,run.profileId),optionName(templates.value,run.templateId),run.writer.model,run.documentType,run.stage];const matchesSearch=!query||values.some(value=>value.toLocaleLowerCase().includes(query));return matchesSearch&&(stateFilter.value==='all'||run.state===stateFilter.value)})})
const templateName=(id:string)=>id?optionName(templates.value,id):t('generate.noTemplate')
const { page, pageSize, visible: visibleRuns } = usePagedList(filteredRuns, [search, stateFilter])

const { models, loadingModelConnections, discover, changeConnection } = useModelDiscovery(
  message => { error.value = message },
  () => t('generate.errors.loadModels'),
)
watch(()=>form.documentType,()=>{if(form.templateId&&!latexTemplates.value.some(item=>item.id===form.templateId))form.templateId=''})
watch(()=>form.templateId,()=>{if(!useSpecifiedModel.value){const choice=form.templateId?templateApplierDefault.value:designerDefault.value;if(choice)form.renderer={...choice};void discover(form.renderer)}})
watch(useSpecifiedModel,value=>{form.pipelineMode=value?'single':'multi';if(value){form.renderer={...form.writer};form.reviewer={...form.writer}}else{form.writer={...(writerDefault.value??form.writer)};form.renderer={...((form.templateId?templateApplierDefault.value:designerDefault.value)??form.writer)};form.reviewer={...(reviewerDefault.value??form.writer)};void Promise.all([discover(form.writer),discover(form.renderer),discover(form.reviewer)])}})
async function load(){try{const [p,j,t,c,g,d]=await Promise.all([api.listProfiles(),api.listJobs(),api.listTemplates(),api.listLLMConnections(),api.listGenerations(),api.getAgentDefaults()]);profiles.value=p.items;opportunities.value=j.items;templates.value=t.items;connections.value=c.items;runs.value=g.items;if(!form.profileId)form.profileId=profiles.value[0]?.id??'';if(!form.opportunityId)form.opportunityId=opportunities.value.find(item=>item.hasDescription)?.id??'';const defaults=Object.fromEntries(d.items.map((item:AgentDefault)=>[item.agent,item]));const valid=(choice?:AgentDefault)=>choice&&connections.value.some(item=>item.id===choice.connectionId)?{connectionId:choice.connectionId,model:choice.model}:undefined;const fallback=valid(defaults.writer)??{connectionId:connections.value[0]?.id??'',model:''};writerDefault.value={...fallback};templateApplierDefault.value=valid(defaults.template_applier)??{...fallback};designerDefault.value=valid(defaults.document_designer)??{...fallback};reviewerDefault.value=valid(defaults.visual_reviewer)??{...fallback};useSpecifiedModel.value=false;form.pipelineMode='multi';form.writer={...fallback};form.renderer={...(designerDefault.value??fallback)};form.reviewer={...(reviewerDefault.value??fallback)};await Promise.all([discover(form.writer),discover(form.renderer),discover(form.reviewer)])}catch(cause){error.value=cause instanceof Error?cause.message:t('generate.errors.loadDocuments')}finally{loading.value=false}}
async function refresh(){try{runs.value=(await api.listGenerations()).items}catch{}if(!active.value&&timer){window.clearInterval(timer);timer=undefined}}
async function generate(){error.value='';submitting.value=true;try{const input:GenerationInput=JSON.parse(JSON.stringify(form));if(input.pipelineMode==='single'){input.renderer={...input.writer};input.reviewer={...input.writer}}await api.createGeneration(input);toast.success(t('generate.toast.queued'));showCreate.value=false;await refresh();if(!timer)timer=window.setInterval(refresh,2000)}catch(cause){error.value=cause instanceof Error?cause.message:t('generate.errors.startGeneration')}finally{submitting.value=false}}
async function removeGeneration(){const run=pendingDelete.value;if(!run)return;deletingId.value=run.id;error.value='';try{await api.deleteGeneration(run.id);runs.value=runs.value.filter(candidate=>candidate.id!==run.id);pendingDelete.value=null;toast.success(t('generate.toast.deleted'))}catch(cause){error.value=cause instanceof Error?cause.message:t('generate.errors.deleteDocument')}finally{deletingId.value=''}}
function openCreate(){error.value='';useSpecifiedModel.value=false;form.pipelineMode='multi';form.writer={...(writerDefault.value??form.writer)};form.renderer={...((form.templateId?templateApplierDefault.value:designerDefault.value)??form.writer)};form.reviewer={...(reviewerDefault.value??form.writer)};void Promise.all([discover(form.writer),discover(form.renderer),discover(form.reviewer)]);showCreate.value=true}
onMounted(async()=>{await load();if(active.value)timer=window.setInterval(refresh,2000)});onBeforeUnmount(()=>{if(timer)window.clearInterval(timer)})
</script>

<template><div class="page generation-page">
  <PageHeader :title="t('pages.generate.title')" :description="t('pages.generate.description')"><button class="button primary" type="button" @click="openCreate">{{ t('generate.createButton') }}</button></PageHeader>
  <p v-if="error&&!showCreate" class="notice error">{{ error }}</p>
  <p v-if="!loading&&!connections.length" class="notice setup-notice">{{ t('generate.setupNotice') }} <RouterLink to="/settings">{{ t('generate.setupNoticeLink') }}</RouterLink></p>
  <div v-if="loading" class="empty-state">{{ t('generate.loadingList') }}</div>
  <section v-else-if="!runs.length" class="empty-state panel"><span class="empty-icon">✦</span><h2>{{ t('generate.emptyState.title') }}</h2><p>{{ t('generate.emptyState.description') }}</p><button class="button primary" type="button" @click="openCreate">{{ t('generate.emptyState.cta') }}</button></section>
  <template v-else><ListFilters v-model:search="search" :total="filteredRuns.length" :search-placeholder="t('generate.searchPlaceholder')"><label>{{ t('generate.statusLabel') }} <select v-model="stateFilter"><option value="all">{{ t('generate.status.all') }}</option><option value="queued">{{ t('generate.status.queued') }}</option><option value="running">{{ t('generate.status.running') }}</option><option value="ready">{{ t('generate.status.ready') }}</option><option value="failed">{{ t('common.needsAttention') }}</option></select></label></ListFilters>
  <TransitionGroup v-if="visibleRuns.length" name="card-list" tag="section" class="application-grid"><article v-for="run in visibleRuns" :key="run.id" class="panel application-card">
    <header><div><span class="document-kind">{{ run.documentType==='resume'?t('generate.documentKind.resume'):t('generate.documentKind.coverLetter') }}</span><h2>{{ optionName(opportunities,run.opportunityId) }}</h2><p>{{ optionName(profiles,run.profileId) }} · {{ templateName(run.templateId) }}</p></div><span class="status-pill" :class="run.state">{{ stageLabel(run) }}</span></header>
    <div class="progress-track"><span :class="run.state" :style="{width:`${stageProgress(run)}%`}" /></div>
    <div class="application-meta"><span>{{ pageTargetLabel(run.pageTarget) }}</span><span>{{ run.pipelineMode==='single'?t('generate.pipelineMode.single'):t('generate.pipelineMode.multi') }}</span><span>{{ formatDate(run.createdAt) }}</span></div>
    <AttentionNotice v-if="run.state==='failed'" compact :message="run.errorMessage||t('generate.attentionFallback')" :code="run.errorCode"/><p v-else-if="run.hasWarning" class="card-message warning-text">{{ t('generate.warningNotice') }}</p>
    <footer><span>{{ run.writer.model }}</span><div class="card-actions"><button class="text-button danger-text" type="button" @click="pendingDelete=run">{{ t('common.delete') }}</button><RouterLink v-if="run.state!=='queued'&&run.state!=='running'" class="text-button" :to="{path:`/generate/${run.id}`,query:{edit:'1'}}">{{ t('common.edit') }}</RouterLink><RouterLink class="button" :to="`/generate/${run.id}`">{{ t('common.view') }}</RouterLink></div></footer>
  </article></TransitionGroup><div v-else class="empty-state compact"><h2>{{ t('generate.noMatching.title') }}</h2><p>{{ t('generate.noMatching.description') }}</p></div><ListPagination v-if="filteredRuns.length" v-model:page="page" v-model:page-size="pageSize" :total="filteredRuns.length" /></template>

  <div v-if="showCreate" class="modal-backdrop" @click.self="showCreate=false"><section class="panel generation-modal" role="dialog" aria-modal="true" aria-labelledby="new-generation-title">
    <header class="modal-header"><div><p class="eyebrow">{{ t('generate.modal.eyebrow') }}</p><h2 id="new-generation-title">{{ t('generate.modal.title') }}</h2></div><button class="modal-close" type="button" :aria-label="t('common.close')" @click="showCreate=false">×</button></header>
    <p v-if="error" class="notice error">{{ error }}</p>
    <form @submit.prevent="generate"><div class="form-grid">
      <label><span>{{ t('generate.modal.documentTypeLabel') }}</span><select v-model="form.documentType"><option value="resume">{{ t('generate.modal.documentTypeResume') }}</option><option value="cover_letter">{{ t('generate.modal.documentTypeCoverLetter') }}</option></select></label><label><span>{{ t('generate.modal.languageLabel') }}</span><input v-model="form.language" required maxlength="40" /></label>
      <label><span>{{ t('generate.modal.profileLabel') }}</span><select v-model="form.profileId" required><option value="" disabled>{{ t('generate.modal.profilePlaceholder') }}</option><option v-for="item in profiles" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label><span>{{ t('generate.modal.opportunityLabel') }}</span><select v-model="form.opportunityId" required><option value="" disabled>{{ t('generate.modal.opportunityPlaceholder') }}</option><option v-for="item in opportunities" :key="item.id" :value="item.id">{{ item.title }} · {{ item.company }}</option></select></label>
      <label><span>{{ t('generate.modal.templateLabel') }}</span><select v-model="form.templateId"><option value="">{{ t('generate.modal.templateNone') }}</option><option v-for="item in latexTemplates" :key="item.id" :value="item.id">{{ item.name }}</option></select><small v-if="!form.templateId">{{ t('generate.modal.templateHelp') }}</small></label><label><span>{{ t('generate.modal.pageTargetLabel') }}</span><select v-model="form.pageTarget"><option value="one_page">{{ t('generate.pageTarget.onePage') }}</option><option value="two_pages">{{ t('generate.pageTarget.twoPages') }}</option><option value="flexible">{{ t('generate.pageTarget.flexible') }}</option></select></label>
      <label class="full"><span>{{ t('generate.modal.customInstructionsLabel') }}</span><textarea v-model="form.customInstructions" rows="3" maxlength="4000" :placeholder="t('generate.modal.customInstructionsPlaceholder')" /></label>
      <div class="full model-routing"><label class="model-switch"><input v-model="useSpecifiedModel" type="checkbox" role="switch" /><span class="model-switch-track" aria-hidden="true"><span /></span><span>{{ t('generate.modal.useSpecificModel') }}</span></label><p v-if="!useSpecifiedModel">{{ t('generate.modal.defaultModelsHelp') }} <RouterLink to="/settings">{{ t('generate.modal.configureAgentModels') }}</RouterLink></p><p v-else>{{ t('generate.modal.specificModelHelp') }}</p></div>
      <fieldset v-if="useSpecifiedModel" class="full model-card"><legend>{{ t('generate.modal.modelForEveryAgent') }}</legend><div class="model-row"><label><span>{{ t('generate.modal.providerLabel') }}</span><select v-model="form.writer.connectionId" @change="changeConnection(form.writer)"><option value="" disabled>{{ t('generate.modal.providerPlaceholder') }}</option><option v-for="item in connections" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label><span>{{ t('generate.modal.modelLabel') }}</span><select v-if="models[form.writer.connectionId]?.length" v-model="form.writer.model" required><option value="" disabled>{{ t('generate.modal.modelPlaceholder') }}</option><option v-for="model in models[form.writer.connectionId]" :key="model" :value="model">{{ model }}</option></select><input v-else v-model="form.writer.model" required :disabled="loadingModelConnections[form.writer.connectionId]" :placeholder="loadingModelConnections[form.writer.connectionId]?t('generate.modal.loadingModels'):t('generate.modal.enterModelName')" /></label></div><small>{{ t('generate.modal.textOnlyModelHelp') }}</small></fieldset>
    </div><div class="modal-actions"><button class="button" type="button" @click="showCreate=false">{{ t('common.cancel') }}</button><button class="button primary" :disabled="!ready||submitting">{{ submitting?t('generate.queuing'):t('generate.modal.submit') }}</button></div></form>
  </section></div>
  <ConfirmDialog :open="Boolean(pendingDelete)" :title="t('generate.deleteDialog.title')" :message="pendingDelete ? t('generate.deleteDialog.message', { name: optionName(opportunities, pendingDelete.opportunityId) }) : ''" :busy="deletingId===pendingDelete?.id" @cancel="pendingDelete=null" @confirm="removeGeneration" />
</div></template>
